head.script:
//
  // FOUC PREVENTION: Lê o tema antes do <body> renderizar
  const savedTheme = localStorage.getItem('biolink-theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  document.documentElement.setAttribute('data-bs-theme', savedTheme);
//

head.b:skin:

/*
<Group description="🎨 Cores do Tema (BioLink Pro)" selector=":root">
  <Variable name="cor.primaria" description="Cor Principal (Botões e Ciano do Fundo)" type="color" default="#00f2fe" value="#00f2fe"/>
  <Variable name="cor.secundaria" description="Cor Secundária (Hover e Roxo do Fundo)" type="color" default="#4facfe" value="#4facfe"/>
</Group>
*/

:root {
  --bio-primary: $(cor.primaria);
  --bio-secondary: $(cor.secundaria);
}
:root {
  /* Paleta Light Mode */
  --bio-bg: #f4f7f6;
  --bio-text: #1e293b;
  --bio-card-bg: rgba(255, 255, 255, 0.7);
  --bio-card-border: rgba(255, 255, 255, 0.5);
  --bio-card-shadow: 0 10px 25px rgba(0, 0, 0, 0.06);
  --bio-card-hover-bg: rgba(255, 255, 255, 0.9);
  --bio-card-hover-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);

  /* Cores de Destaque */
  --bio-primary: #06b6d4; /* Ciano */
  --bio-secondary: #8b5cf6; /* Roxo */

  --font-main: 'Plus Jakarta Sans', sans-serif;
}

[data-bs-theme="dark"] {
  /* Paleta Dark Mode (Midnight Glass) */
  --bio-bg: #0a0a0a;
  --bio-text: #f8fafc;
  --bio-card-bg: rgba(25, 25, 25, 0.4);
  --bio-card-border: rgba(255, 255, 255, 0.05);
  --bio-card-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  --bio-card-hover-bg: rgba(255, 255, 255, 0.08);
  --bio-card-hover-shadow: 0 0 20px rgba(6, 182, 212, 0.3);
}

/* === ESTILOS GLOBAIS === */
body {
  background-color: var(--bio-bg);
  color: var(--bio-text);
  font-family: var(--font-main);
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.4s ease, color 0.4s ease;
  position: relative;
  overflow-x: hidden;
}

a { text-decoration: none; }

/* === BLOBS ANIMADOS (O SEGREDO DO GLASSMORPHISM) === */
.background-blobs {
  position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
  overflow: hidden; z-index: -1; pointer-events: none;
}
.blob {
  position: absolute; border-radius: 50%; filter: blur(80px);
  opacity: 0.6; animation: blob-float 20s infinite alternate ease-in-out;
}
.blob-1 {
  width: 400px; height: 400px; background: var(--bio-secondary);
  top: -100px; left: -100px; animation-delay: 0s;
}
.blob-2 {
  width: 300px; height: 300px; background: var(--bio-primary);
  bottom: -50px; right: -50px; animation-delay: -5s;
}
[data-bs-theme="dark"] .blob { opacity: 0.3; }

@keyframes blob-float {
  0% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(150px, 100px) scale(1.2); }
  100% { transform: translate(50px, 200px) scale(0.9); }
}

/* === 1. CABEÇALHO / PERFIL === */
.profile-img-wrapper {
  width: 120px; height: 120px; padding: 4px; border-radius: 50%;
  background: linear-gradient(45deg, var(--bio-primary), var(--bio-secondary));
  animation: pulse-ring 3s infinite cubic-bezier(0.215, 0.61, 0.355, 1);
}

.profile-img {
  width: 100%; height: 100%; border: 4px solid var(--bio-bg);
  background-color: var(--bio-bg); transition: border-color 0.4s ease;
}

.profile-name { letter-spacing: -0.5px; color: var(--bio-text); }
.profile-bio { font-size: 1rem; opacity: 0.75; }

/* === 2. BOTÕES DE LINKS === */
.links-container { width: 100%; max-width: 550px; margin: 0 auto; }

.link-btn {
  background-color: var(--bio-card-bg);
  border: 1px solid var(--bio-card-border);
  color: var(--bio-text) !important;
  border-radius: 50px;
  padding: 16px 24px;
  font-size: 1.05rem;
  letter-spacing: 0.3px;
  box-shadow: var(--bio-card-shadow);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.link-btn:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: var(--bio-card-hover-shadow);
  background-color: var(--bio-card-hover-bg);
  border-color: var(--bio-primary);
}

/* === 3. REDES SOCIAIS (FOOTER) === */
.social-icon-btn {
  color: var(--bio-text);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  opacity: 0.7;
}
.social-icon-btn:hover {
  color: var(--bio-primary);
  opacity: 1;
  transform: scale(1.2) translateY(-3px);
}

/* === 4. CONTROLES (PARTILHAR E TEMA) === */
.footer-controls .btn {
  background-color: var(--bio-card-bg);
  border: 1px solid var(--bio-card-border);
  color: var(--bio-text);
  box-shadow: var(--bio-card-shadow);
  transition: all 0.3s ease;
  font-size: 0.85rem;
  letter-spacing: 0.5px;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.footer-controls .btn:hover {
  background: linear-gradient(45deg, var(--bio-primary), var(--bio-secondary));
  color: #ffffff;
  border-color: transparent;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(139, 92, 246, 0.3);
}

/* === ANIMAÇÕES CSS NATIVAS === */
@keyframes pulse-ring {
  0% { box-shadow: 0 0 0 0 rgba(139, 92, 246, 0.5); }
  70% { box-shadow: 0 0 0 15px rgba(139, 92, 246, 0); }
  100% { box-shadow: 0 0 0 0 rgba(139, 92, 246, 0); }
}

/* Cascata */
.animate-item { animation: fadeInUp 0.6s ease backwards; position: relative; z-index: 10; }
header.animate-item { animation-delay: 0.1s; }
main.animate-item { animation-delay: 0.2s; }
footer .animate-item { animation-delay: 0.3s; }
.links-container .link-btn { animation: fadeInUp 0.5s ease backwards; }
.links-container .link-btn:nth-child(1) { animation-delay: 0.2s; }
.links-container .link-btn:nth-child(2) { animation-delay: 0.3s; }
.links-container .link-btn:nth-child(3) { animation-delay: 0.4s; }
.links-container .link-btn:nth-child(4) { animation-delay: 0.5s; }
.links-container .link-btn:nth-child(5) { animation-delay: 0.6s; }

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

body.script:
//
document.addEventListener('DOMContentLoaded', () => {

  /* === 1. TEMA ESCURO INTELIGENTE === */
  const btnTheme = document.getElementById('btnTheme');
  const themeIcon = btnTheme ? btnTheme.querySelector('i') : null;

  const setTheme = (theme) => {
    document.documentElement.setAttribute('data-bs-theme', theme);
    localStorage.setItem('biolink-theme', theme);
    if (themeIcon) {
      themeIcon.className = theme === 'dark' ? 'bi bi-sun-fill me-2' : 'bi bi-moon-stars-fill me-2';
    }
  };

  if (themeIcon) {
    themeIcon.className = document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'bi bi-sun-fill me-2' : 'bi bi-moon-stars-fill me-2';
  }

  if (btnTheme) {
    btnTheme.addEventListener('click', () => {
      const currentTheme = document.documentElement.getAttribute('data-bs-theme');
      setTheme(currentTheme === 'dark' ? 'light' : 'dark');
    });
  }

  /* === 2. PARTILHA NATIVA BLINDADA (WEB SHARE API) === */
  const btnShare = document.getElementById('btnShare');
  let isSharing = false; /* Trava anti-spam de cliques */

  if (btnShare) {
    btnShare.addEventListener('click', async () => {
      if (isSharing) return; /* Se já estiver a partilhar, ignora o clique */

      if (navigator.share) {
        try {
          await navigator.share({
            title: document.title,
            text: 'Confere os meus links!',
            url: window.location.href
          });
        } catch (err) {
          console.log('Partilha cancelada.');
        }
      } else {
        /* Fallback Seguro para PC/Navegadores Antigos */
        isSharing = true;
        navigator.clipboard.writeText(window.location.href);
        btnShare.innerHTML = '<i class="bi bi-check2-circle me-2"></i> Copiado!';

        setTimeout(() => { 
          btnShare.innerHTML = '<i class="bi bi-share-fill me-2"></i> Partilhar'; 
          isSharing = false; /* Liberta a trava */
        }, 2500);
      }
    });
  }

  /* === 3. MOTOR DE ÍCONES SOCIAIS (100% CORRIGIDO) === */
  const socialLinks = document.querySelectorAll('.social-icon-btn');
  socialLinks.forEach(link => {
    const url = link.href.toLowerCase();
    const icon = link.querySelector('i');
    if (!icon) return;

    if (url.includes('instagram.com')) icon.className = 'bi bi-instagram';
    else if (url.includes('twitter.com') || url.includes('x.com')) icon.className = 'bi bi-twitter-x';
    else if (url.includes('facebook.com')) icon.className = 'bi bi-facebook';
    else if (url.includes('youtube.com') || url.includes('youtu.be')) icon.className = 'bi bi-youtube';
    else if (url.includes('tiktok.com')) icon.className = 'bi bi-tiktok';
    else if (url.includes('whatsapp.com') || url.includes('wa.me')) icon.className = 'bi bi-whatsapp';
    else if (url.includes('linkedin.com')) icon.className = 'bi bi-linkedin';
    else if (url.includes('github.com')) icon.className = 'bi bi-github';
    else if (url.includes('spotify.com')) icon.className = 'bi bi-spotify'; /* BUG REALMENTE CORRIGIDO AGORA */
    else if (url.includes('twitch.tv')) icon.className = 'bi bi-twitch';
    else if (url.includes('threads.net')) icon.className = 'bi bi-threads';
    else if (url.includes('t.me') || url.includes('telegram.org')) icon.className = 'bi bi-telegram';
    else if (url.includes('snapchat.com')) icon.className = 'bi bi-snapchat';
    else if (url.includes('pinterest.com')) icon.className = 'bi bi-pinterest';
    else if (url.includes('mailto:')) icon.className = 'bi bi-envelope-at-fill';
  });

});
//
